using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPlayerCorruptEnemyOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/OnPlayerCorruptEnemy Omen Data")]
public class OnPlayerCorruptEnemyOmenData : OmenData
{
	protected const string wheneverCorruptEnemyChantID = "CorruptEnemyChant";

	protected const string corruptEnemyMinimumChantID = "CorruptEnemyMinimumChant";

	[Header("On Player Corrupt Enemy Omen")]
	[SerializeField]
	private int minimumCorruptAmount;

	private Action<GameObject, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate(GameObject enemyTarget, int corruptAmount)
		{
			if (IsMinimunCorruptAmount(corruptAmount))
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				ActivateOnCorruptEnemyOmen(enemyTarget);
			}
		};
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptEnemyOmenActions.Add(omenAction);
	}

	protected virtual void ActivateOnCorruptEnemyOmen(GameObject enemyTarget)
	{
		ActivateOmen(enemyTarget);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<MiscOmensHandler>.Instance.OnPlayerCorruptEnemyOmenActions.Remove(omenAction);
	}

	private bool IsMinimunCorruptAmount(int corruptAmount)
	{
		return corruptAmount >= minimumCorruptAmount;
	}

	public override string OmenConvertedDescription()
	{
		return GetOnCorruptEnemyDescription() + base.localizationManager.GetLocalizedSpace() + base.OmenConvertedDescription();
	}

	protected string GetOnCorruptEnemyDescription()
	{
		string text = "";
		if (minimumCorruptAmount <= 1)
		{
			return GetWheneverCorruptEnemyChantLocalized();
		}
		return Smart.Format(base.localizationManager.GetLocalizedString("CorruptEnemyMinimumChant"), minimumCorruptAmount);
	}

	public string GetWheneverCorruptEnemyChantLocalized()
	{
		return base.localizationManager.GetLocalizedString("CorruptEnemyChant");
	}
}
